<template><q-page><div class="page-wrap"><PageHeader title="Developer handoff" subtitle="Screen coverage, connected journeys and the boundary between this mockup and the production system." eyebrow="Implementation reference"><template #actions><q-btn outline no-caps color="primary" label="Download guide" icon="download" @click="downloadGuide"/><q-btn unelevated no-caps color="primary" label="Source repository" icon="code" href="https://github.com/avsalang/Saferseasdashboard-main/tree/main/prototype" target="_blank" rel="noopener"/></template></PageHeader><div class="metric-grid"><div class="metric-card"><div class="muted">Specified screen coverage</div><div class="metric-value">49</div><div class="text-caption muted">Shared, reporter, operations, data, administration</div></div><div class="metric-card"><div class="muted">Output catalogue</div><div class="metric-value">22</div><div class="text-caption muted">Audited table, form, map & figure families</div></div><div class="metric-card"><div class="muted">Runtime</div><div class="metric-value" style="font-size:24px">Vue / Quasar</div><div class="text-caption muted">Browser-local fictional demonstration</div></div></div>
<q-tabs v-model="tab" align="left" no-caps active-color="primary" indicator-color="primary" class="q-mb-lg"><q-tab name="journeys" label="Walkthroughs"/><q-tab name="screens" label="Screens & routes"/><q-tab name="architecture" label="Data & integration"/><q-tab name="limitations" label="Scope & decisions"/></q-tabs>
<template v-if="tab==='journeys'"><div class="panel" v-for="(j,i) in journeys" :key="j.title"><div class="eyebrow">JOURNEY {{i+1}}</div><h3>{{j.title}}</h3><p class="muted">{{j.steps}}</p><div class="row q-gutter-sm"><q-btn v-for="link in j.links" :key="link.to" outline no-caps color="primary" :label="link.label" :to="link.to"/></div></div><div class="help-note">Switch accounts by signing out and selecting the appropriate demo account at sign-in. All three account types can report, review, investigate and produce outputs within their assigned record scope. Central account and configuration controls require MARINA Investigator access.</div></template>
<section v-else-if="tab==='screens'" class="panel"><div class="toolbar-row"><q-input v-model="search" outlined dense clearable label="Find screen / route" style="min-width:270px"/><q-space/><span class="muted text-caption">{{screenRoutes.length}} route entries; shared detail/form routes cover related screen IDs</span></div><q-table flat row-key="path" :rows="screenRoutes" :columns="columns" :filter="search" :pagination="{rowsPerPage:15}" wrap-cells><template #body-cell-open="p"><q-td :props="p"><q-btn flat no-caps color="primary" dense label="Open" :to="samplePath(p.row.path)"/></q-td></template></q-table></section>
<template v-else-if="tab==='architecture'"><div class="content-grid"><section class="panel"><h3>Domain relationships</h3><q-list separator><q-item v-for="d in domain" :key="d.name"><q-item-section><q-item-label class="text-weight-bold">{{d.name}}</q-item-label><q-item-label caption>{{d.desc}}</q-item-label></q-item-section></q-item></q-list></section><section class="panel"><h3>Production integration</h3><p class="muted">Replace the browser-local store with an authenticated API while retaining the forms, selections and action contracts.</p><ul class="muted"><li>Issued account activation, authentication and revocation</li><li>Scoped event, vessel, case and evidence resources</li><li>Server-validated status transitions and immutable report revisions</li><li>Staged import, provenance and duplicate decisions</li><li>Snapshot-based report jobs and protected artifacts</li><li>Auditable permissions on every endpoint</li></ul><q-btn flat no-caps color="primary" label="Read repository documentation" href="https://github.com/avsalang/Saferseasdashboard-main/tree/main/prototype/docs" target="_blank" rel="noopener"/></section></div></template>
<template v-else><section class="panel"><h3>What this demonstration does</h3><p class="muted">Navigable role-specific screens, local drafts/edits/transitions, multi-vessel records, typed investigation/case data, sample imports, filtered maps/analytics, real CSV/XLSX/GeoJSON downloads and browser-print report previews.</p><h3 class="q-mt-lg">What requires the production backend</h3><p class="muted">Actual identity verification, secure roles/sessions, email/invitation delivery, shared databases, file upload/storage, background report/import jobs, authoritative risk scoring and issued official PDFs. Client-side role guards are illustrative, not a security boundary.</p><h3 class="q-mt-lg">MARINA decisions still needed</h3><q-list><q-item v-for="v in decisions" :key="v"><q-item-section avatar><q-icon name="radio_button_unchecked" size="16px"/></q-item-section><q-item-section>{{v}}</q-item-section></q-item></q-list><p class="help-note q-mt-lg">No original MARINA records or evidence files are included. The published Pages site is a fictional design demonstration; the intended production platform remains account-only.</p></section></template>
</div></q-page></template>
<script setup>import{ref,computed}from'vue';import{useRouter}from'vue-router';import PageHeader from'../components/PageHeader.vue';import{useDemo}from'../stores/demo.js';const store=useDemo(),router=useRouter(),tab=ref('journeys'),search=ref('');const screenRoutes=computed(()=>router.getRoutes().filter(r=>r.meta.screenId).map(r=>({path:r.path,id:r.meta.screenId,title:r.meta.title,permission:r.meta.permission||r.meta.roles?.join(', ')||'Active issued account'})).sort((a,b)=>a.id.localeCompare(b.id)));const columns=[{name:'id',label:'Screen',field:'id',align:'left',sortable:true},{name:'title',label:'Page',field:'title',align:'left',sortable:true},{name:'path',label:'Route',field:'path',align:'left'},{name:'permission',label:'Access',field:'permission',align:'left'},{name:'open',label:'',field:'path'}];const samplePath=p=>p.replace(':outputId','O01').replace(':id',p.includes('cases')?'case-001':p.includes('imports')?'batch-001':p.includes('risk')?store.state.assessments[0]?.id||'new':'e-003');const journeys=[{title:'Issued account → report → validation',steps:'Reporter signs in, saves a multi-vessel draft and submits. Staff review the same record; corrections produce a reporter notification and a retained resubmission timeline.',links:[{label:'Reporter reports',to:'/reporter/reports'},{label:'Review queue',to:'/admin/review'}]},{title:'Investigation → report revisions → follow-up',steps:'Assign the investigator, prepare MAIC 1B, add repeatable Form2 progress revisions, then prepare Form3B final findings and assigned recommendations.',links:[{label:'Investigations',to:'/admin/investigations'},{label:'Follow-up actions',to:'/admin/actions'}]},{title:'Enforcement case → SCO → outcome',steps:'Link the event, vessel and party; record multiple orders, actual issuing office, issue-time precision, violation references, penalties and suspension/lifting actions.',links:[{label:'Case register',to:'/admin/cases'}]},{title:'Historical import → reconciliation',steps:'Use the fictional sample; review source mapping, merged event/vessel groups, errors and duplicate candidates before confirming the local import.',links:[{label:'Start sample import',to:'/admin/imports/new'},{label:'Reconciliation',to:'/admin/reconciliation'}]},{title:'Selection → analysis → reproducible output',steps:'Choose a population, compare exact seriousness/event/vessel totals, inspect location quality and generate a complete selected output with snapshot metadata.',links:[{label:'Analytics',to:'/admin/analytics'},{label:'GIS workspace',to:'/admin/map'},{label:'Output catalogue',to:'/admin/reports'}]},{title:'Account lifecycle and accountable access',steps:'The MARINA Investigator issues an invitation, assigns role and office, previews activation and suspends/reactivates the account without erasing historical attribution.',links:[{label:'Account management',to:'/admin/accounts'},{label:'Roles',to:'/admin/roles'}]},{title:'Template and audit handoff',steps:'Review proposed template requirements and separate lifecycle states; inspect action attribution and export the audit register.',links:[{label:'Workflow & templates',to:'/admin/workflows'},{label:'Audit trail',to:'/admin/audit'}]}];const domain=[{name:'Event → involved vessels',desc:'One occurrence; multiple incident-time vessel snapshots. Distinct event/involvement counting.'},{name:'Investigation reports → revisions',desc:'Spot,1B,2 and3B documents with prepared/noted dates, observations and retained issued revisions.'},{name:'Enforcement case → legal actions',desc:'Cases, parties, SCOs, decisions, penalties, conditions and suspension/lifting timelines.'},{name:'Consequences → knowledge state',desc:'Nullable human/ship/environment outcomes. Zero, unknown and unallocated totals differ.'},{name:'Source rows → import decisions',desc:'File/sheet/row/merge provenance, errors, duplicates and approved grouping.'},{name:'Report selection → output snapshot',desc:'Period/as-of, office roles, counting grain, template version and full selection metadata.'}];const decisions=['Approved source snapshots and counting rules for each output','Exact role/office scope and account/session lifecycle','SCO/progress timing basis and unknown-time handling','Official editable form masters, Form1A, paper size and signatories','GT band boundaries and historic vessel-age reference date','Approved AOR boundaries, location confidence and hotspot settings','Record retention, sharing/export authority and operational audit requirements'];function downloadGuide(){const body='# SAFERSEAS Vue/Quasar developer handoff\n\nKeep the original seven-section SAFERSEAS incident form, map picking and weather assistance; add missing MAIC information within those sections. Detailed progress/final investigation and signoffs remain in the investigation workspace.\n\nFull handoff: https://github.com/avsalang/Saferseasdashboard-main/blob/main/prototype/docs/DEVELOPER_HANDOFF.md\nForm additions: https://github.com/avsalang/Saferseasdashboard-main/blob/main/prototype/docs/INCIDENT_FORM_ADDITIONS.md\n\n'+journeys.map((j,i)=>`## Journey ${i+1}: ${j.title}\n${j.steps}\n`).join('\n')+'\n## Screens\n'+screenRoutes.value.map(r=>`${r.id} | ${r.title} | ${r.path} | ${r.permission}`).join('\n')+'\n\n## Production responsibilities\nReal identity, server authorization, email, storage, imports and report jobs require backend implementation. This demo stores fictional records in this browser.\n\n## MARINA decisions\n'+decisions.map(d=>'- '+d).join('\n');const url=URL.createObjectURL(new Blob([body],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='SAFERSEAS_DEVELOPER_HANDOFF.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}</script>
